import type { SerializableRuntimeValue } from "../../src/runtime/values/serializable-values.js";

/*
 * Written-domain matrices (the lead's rulings on the merged S6's B1 and B2; A4, F17b, §4's fit rule; ADR 0021 1.3;
 * V30 §13): a written type, or a copy of one, admits exactly what the type permits at every level, whatever is stored.
 * Each case is generated by axes from a V30 §13 form; every expectation is the form's own: the admitted kinds per level,
 * the checked type of each store that brings a host value, and which host values fit.
 */

/** A written type form of V30 §13: a type name, `T?`, `T | U`, or a list, set or dict of a form. */
type Form =
  | { readonly kind: "name"; readonly name: string }
  | { readonly kind: "optional"; readonly of: Form }
  | { readonly kind: "union"; readonly members: readonly Form[] }
  | { readonly kind: "collection"; readonly collection: Collection; readonly of: Form };

type Collection = "list" | "set" | "dict";

/** V30 §13's type names: the scalars, `null`, the unrestricted collections and `object`, the program-control names. */
const SCALAR_NAMES = [
  "string",
  "boolean",
  "integer",
  "number",
  "date",
  "time",
  "datetime",
  "absoluteDateTime",
  "duration",
  "calendarDuration",
  "angle",
] as const;
const UNRESTRICTED_NAMES = ["list", "set", "dict", "object"] as const;
const CONTROL_NAMES = [
  "range",
  "speaker",
  "timer",
  "media",
  "messageHandle",
  "script",
  "regex",
] as const;

const UNRESTRICTED: ReadonlySet<string> = new Set(UNRESTRICTED_NAMES);

const name = (of: string): Form => ({ kind: "name", name: of });
const optional = (of: Form): Form => ({ kind: "optional", of });
const union = (...members: Form[]): Form => ({ kind: "union", members });
const collection = (kind: Collection, of: Form): Form => ({
  kind: "collection",
  collection: kind,
  of,
});

/** The form as the source writes it. */
function formText(form: Form): string {
  const grouped = (of: Form): string => (of.kind === "union" ? `(${formText(of)})` : formText(of));
  switch (form.kind) {
    case "name":
      return form.name;
    case "optional":
      return `${grouped(form.of)}?`;
    case "union":
      return form.members.map(formText).join(" | ");
    case "collection":
      return `${grouped(form.of)}${form.collection === "list" ? "[]" : ` ${form.collection}`}`;
  }
}

/** The members a level of a form holds: an optional's form and `null`, a union's members. */
function members(form: Form): Form[] {
  if (form.kind === "optional") return [...members(form.of), name("null")];
  if (form.kind === "union") return form.members.flatMap(members);
  return [form];
}

/**
 * The kinds the form admits at each level of its element path, sorted, from its root down: a name its kind, a
 * collection its kind with its element's level below, an unrestricted collection's element `unknown` (every kind).
 */
function levelsOf(form: Form): string[][] {
  const out: string[][] = [];
  let level: Form[] = [form];
  for (;;) {
    const kinds = new Set<string>();
    const below: Form[] = [];
    let open = false;
    for (const member of level.flatMap(members))
      if (member.kind === "name") {
        kinds.add(member.name);
        if (member.name !== "object" && UNRESTRICTED.has(member.name)) open = true;
      } else if (member.kind === "collection") {
        kinds.add(member.collection);
        below.push(member.of);
      }
    out.push([...kinds].sort());
    if (below.length === 0) {
      if (open) out.push(["unknown"]);
      return out;
    }
    level = below;
  }
}

/** The whole type the plan checks a store of the form against, as the tests print a `TypePlan`. */
function checkedText(form: Form): string {
  switch (form.kind) {
    case "name":
      return form.name !== "object" && UNRESTRICTED.has(form.name)
        ? `${form.name}<any>`
        : form.name;
    case "optional":
      return `${checkedText(form.of)}|null`;
    case "union":
      return form.members.map(checkedText).join("|");
    case "collection":
      return `${form.collection}<${checkedText(form.of)}>`;
  }
}

/** A value of the form with `leaf` at its innermost element: a list's `[ ]`, a set's `set[ ]`, a dict's `dict{a: }`. */
function valueOf(form: Form, leaf: string): string {
  switch (form.kind) {
    case "name":
      return leaf;
    case "optional":
      return valueOf(form.of, leaf);
    case "union":
      return valueOf(form.members[0]!, leaf);
    case "collection":
      return form.collection === "list"
        ? `[${valueOf(form.of, leaf)}]`
        : form.collection === "set"
          ? `set[${valueOf(form.of, leaf)}]`
          : `dict{a: ${valueOf(form.of, leaf)}}`;
  }
}

/** The kinds the innermost element `valueOf` places admits: a name's, an optional's with `null`, a union's. */
function leafKinds(form: Form): string[] {
  switch (form.kind) {
    case "name":
      return [form.name];
    case "optional":
      return form.of.kind === "collection" ? leafKinds(form.of) : [...leafKinds(form.of), "null"];
    case "union":
      return form.members.flatMap(leafKinds);
    case "collection":
      return leafKinds(form.of);
  }
}

/** A literal of a form's innermost name, where V30 has one the slice reads. */
const LITERALS: Readonly<Record<string, string>> = {
  integer: "1",
  number: "1.5",
  string: '"a"',
  boolean: "true",
  null: "null",
  list: "[1]",
};

function leafLiteral(form: Form): string | null {
  switch (form.kind) {
    case "name":
      return LITERALS[form.name] ?? null;
    case "optional":
      return leafLiteral(form.of);
    case "union":
      return leafLiteral(form.members[0]!);
    case "collection":
      return leafLiteral(form.of);
  }
}

/** The host values every run tries, each with the kinds it is: a value fits a level that admits one of them. */
const HOST_VALUES: readonly (readonly [SerializableRuntimeValue, readonly string[]])[] = [
  [2, ["integer", "number"]],
  [2.5, ["number"]],
  ["text", ["string"]],
  [true, ["boolean"]],
  [null, ["null"]],
  [{ kind: "list", items: [1] }, ["list"]],
];

type Decision =
  | "written"
  | "early copy"
  | "later copy"
  | "copy of a copy"
  | "copy of a copy of a copy"
  | "projection"
  | "copy of a projection"
  | "copy of a later-typed copy"
  | "copy of an otherwise"
  | "copy of a get default";

type Host = "direct" | "named" | "index-held";

const HOSTS: readonly Host[] = ["direct", "named", "index-held"];

/** One source: its place, the form it holds, what each level admits, the checked stores and which values fit. */
export interface WrittenCase {
  readonly name: string;
  readonly source: string;
  /** The binding under test: the written one, or the copy. */
  readonly place: string;
  readonly form: string;
  /** How the place under test is decided (`Decision`), for the test's account of what the route takes. */
  readonly decision: string;
  readonly levels: readonly (readonly string[])[];
  /** The plan's checked stores in order, `start:end type`, where the candidate route takes the source. */
  readonly checks: readonly string[];
  /**
   * Whether `checks` are all the plan's: with a literal initial value; with the host value as the initial value too, a
   * copy of the written binding may be checked as well.
   */
  readonly exact: boolean;
  /** Per host value, `null` where it fits, else where it stops (`TSR058@start:end`). */
  readonly runs: readonly (readonly [SerializableRuntimeValue, string | null])[];
  /**
   * The program's C9 boundaries, sorted, each `root level [kinds] start:end`: one per store that brings the host value,
   * at the host read, against what its destination admits at the level it lands at; none where that level admits every
   * kind; a named host value's at its own unwritten binding, which nothing decides (`[unknown]`).
   */
  readonly boundaries: readonly string[];
}

/** The level `valueOf`'s leaf stands at: its collections' nesting along the first members. */
function leafDepth(form: Form): number {
  switch (form.kind) {
    case "name":
      return 0;
    case "optional":
      return leafDepth(form.of);
    case "union":
      return leafDepth(form.members[0]!);
    case "collection":
      return 1 + leafDepth(form.of);
  }
}

/** The C9 boundary a host read at `site` owes where it lands in `root` at `level` of `levels`, if any (`boundaries`). */
function boundaryAt(
  root: string,
  levels: readonly (readonly string[])[],
  level: number,
  site: string,
): string[] {
  const kinds = levels[level]!;
  return kinds.includes("unknown")
    ? []
    : [`${root} ${level} [${[...kinds].sort().join(",")}] ${site}`];
}

/** The site of `of` in `line` of `source`, as `start:end`. */
function siteIn(source: string, line: string, of: string): string {
  const start = source.indexOf(`${line}\n`) + line.indexOf(of);
  return `${start}:${start + of.length}`;
}

/**
 * The source of `form` under `decision` with the host value `host`: `typed` written with the form, initialised with a
 * literal of it (else the host value), then the place that receives the host value (`typed` itself, a copy taken
 * before or after that store, a copy at the end of a chain of two or three copies, or, with `projection`, a copy of the
 * written list's element, with `copy of a projection` a copy of that copy; or a copy of a place whose written type comes
 * later than its start, `[]` for a list and `null` otherwise, through a selected `otherwise`, or as an empty list's
 * `get` default: the seeds of Sol's round 2).
 */
function writtenCase(form: Form, decision: Decision, host: Host): WrittenCase {
  const type = formText(form);
  const literal = leafLiteral(form);
  const init = valueOf(form, literal ?? "hostValue");
  const projected = decision === "projection" || decision === "copy of a projection";
  const placed = projected && form.kind === "collection" ? form.of : form;
  const leaf = host === "direct" ? "hostValue" : host === "named" ? "h" : "[hostValue][0]";
  // (a later copy's host store holds the host value whole: a literal around it would decide its levels first, A2)
  const value = decision === "later copy" ? leaf : valueOf(placed, leaf);
  const lines = [
    ...(host === "named" ? ["let h = hostValue"] : []),
    `let typed: ${type} = ${init}`,
  ];
  let hostLine: string;
  switch (decision) {
    case "written":
      hostLine = `typed = ${value}`;
      lines.push(hostLine);
      break;
    case "early copy":
      hostLine = `copy = ${value}`;
      lines.push("let copy = typed", hostLine);
      break;
    case "later copy":
      hostLine = `let copy = ${value}`;
      lines.push(hostLine, "copy = typed");
      break;
    case "copy of a copy":
      hostLine = `copy = ${value}`;
      lines.push("let middle = typed", "let copy = middle", hostLine);
      break;
    case "copy of a copy of a copy":
      hostLine = `copy = ${value}`;
      lines.push("let first = typed", "let second = first", "let copy = second", hostLine);
      break;
    case "projection":
      hostLine = `copy = ${value}`;
      lines.push("let copy = typed[0]", hostLine);
      break;
    case "copy of a projection":
      hostLine = `copy = ${value}`;
      lines.push("let middle = typed[0]", "let copy = middle", hostLine);
      break;
    case "copy of a later-typed copy":
      hostLine = `copy = ${value}`;
      lines.push(
        `let middle = ${form.kind === "collection" && form.collection === "list" ? "[]" : "null"}`,
        "middle = typed",
        "let copy = middle",
        hostLine,
      );
      break;
    case "copy of an otherwise":
      hostLine = `copy = ${value}`;
      lines.push("let middle = null otherwise typed", "let copy = middle", hostLine);
      break;
    case "copy of a get default":
      hostLine = `copy = ${value}`;
      lines.push("let middle = [].get(0, default: typed)", "let copy = middle", hostLine);
      break;
  }
  const source = `${[...lines, 'say "DONE"', "exit"].join("\n")}\n`;
  const span = (line: string, of: string): { store: string; value: string } => {
    const start = source.indexOf(`${line}\n`);
    const end = start + line.length;
    return { store: `${start}:${end}`, value: `${end - of.length}:${end}` };
  };
  // the stores that check a host value, in order: the initial value at the leaf where there is no literal, then the
  // host store's, at the leaf or whole
  const stores = [
    ...(literal === null
      ? [{ ...span(`let typed: ${type} = ${init}`, init), whole: false, of: form }]
      : []),
    { ...span(hostLine, value), whole: decision === "later copy", of: placed },
  ];
  const runs = HOST_VALUES.map(
    ([given, is]): readonly [SerializableRuntimeValue, string | null] => {
      const stop = stores.find((store) => !fitsAt(store.of, store.whole, is));
      return [given, stop === undefined ? null : `TSR058@${stop.value}`];
    },
  );
  const place = decision === "written" ? "typed" : "copy";
  const boundaries = [
    ...(literal === null
      ? boundaryAt(
          "typed",
          levelsOf(form),
          leafDepth(form),
          siteIn(source, `let typed: ${type} = ${init}`, "hostValue"),
        )
      : []),
    ...(host === "named"
      ? [`h 0 [unknown] ${siteIn(source, "let h = hostValue", "hostValue")}`]
      : boundaryAt(
          place,
          levelsOf(placed),
          decision === "later copy" ? 0 : leafDepth(placed),
          siteIn(source, hostLine, "hostValue"),
        )),
  ];
  return {
    name: `${type}, ${decision}, ${host}`,
    source,
    place,
    form: formText(placed),
    decision,
    levels: levelsOf(placed),
    checks: stores.map(({ store, of }) => `${store} ${checkedText(of)}`),
    exact: literal !== null,
    runs,
    boundaries: boundaries.sort(),
  };
}

/**
 * Whether a host value of the kinds `is` fits a form: at its innermost element (`valueOf`'s leaf), or whole, a list
 * value's element (an integer, `HOST_VALUES`) fitting the level below.
 */
function fitsAt(form: Form, whole: boolean, is: readonly string[]): boolean {
  if (!whole) return is.some((kind) => leafKinds(form).includes(kind));
  const levels = levelsOf(form);
  if (!is.some((kind) => levels[0]!.includes(kind))) return false;
  if (!is.includes("list") || levels.length < 2) return true;
  return (
    levels[1]!.includes("unknown") ||
    ["integer", "number"].some((kind) => levels[1]!.includes(kind))
  );
}

/** A form's depth: its collections' nesting. */
function depthOf(form: Form): number {
  switch (form.kind) {
    case "name":
      return 0;
    case "optional":
      return depthOf(form.of);
    case "union":
      return Math.max(...form.members.map(depthOf));
    case "collection":
      return 1 + depthOf(form.of);
  }
}

/**
 * The decisions the matrices take: the written place, an early or a later copy, and a copy at the end of a chain of two
 * or three whole copies (A4 reaches through them: the lead's ruling on chains).
 */
const DECISIONS: readonly Decision[] = [
  "written",
  "early copy",
  "later copy",
  "copy of a copy",
  "copy of a copy of a copy",
];

/** The decisions of a written list's element: a copy of it (a typed index projection), and a copy of that copy. */
const PROJECTIONS: readonly Decision[] = ["projection", "copy of a projection"];

/**
 * Where a copied place's own written type comes from besides a whole copy at its start (Sol's round 2: the seeds): a copy
 * after an untyped start, a selected `otherwise`, an empty list's `get` default; its copy keeps the type (r4.75 (1)).
 */
const SEEDS: readonly Decision[] = [
  "copy of a later-typed copy",
  "copy of an otherwise",
  "copy of a get default",
];

/**
 * The merged S6's B1 (the reviewer's written-domain matrix, rebuilt by axes): nine element domains (the four usual
 * scalars, each optional, and `null` alone) × list depths 0–3, the outermost list optional or not × the place written,
 * an early or a later copy, a copy at the end of a chain of two or three copies, a copy of the written list's element
 * (a typed index projection) or a copy of that copy, a copy of a place typed by each seed (`SEEDS`) × the host value
 * direct, named or held at an index.
 */
export const WRITTEN_DOMAIN_MATRIX: readonly WrittenCase[] = (() => {
  const out: WrittenCase[] = [];
  const domains = ["integer", "number", "string", "boolean"].flatMap((kind) => [
    name(kind),
    optional(name(kind)),
  ]);
  domains.push(name("null"));
  for (const domain of domains)
    for (const depth of [0, 1, 2, 3])
      for (const outerOptional of depth === 0 ? [false] : [false, true]) {
        let form = domain;
        for (let level = 0; level < depth; level += 1) form = collection("list", form);
        if (outerOptional) form = optional(form);
        for (const decision of [...DECISIONS, ...PROJECTIONS, ...SEEDS]) {
          if (PROJECTIONS.includes(decision) && (outerOptional || depth === 0)) continue;
          for (const host of HOSTS) out.push(writtenCase(form, decision, host));
        }
      }
  return out;
})();

/**
 * One source of `UNRESTRICTED_COLLECTION_MATRIX` or `OBJECT_PROPERTY_MATRIX`: contents an unrestricted part takes, which
 * every kind fits, so nothing is owed.
 */
export interface UnrestrictedCase {
  readonly name: string;
  readonly source: string;
  readonly place: string;
  /** The steps from the place down to its unrestricted part: elements, a property. */
  readonly path: readonly string[];
  /** The kinds the place admits at each prefix of `path`, from the place itself, `unknown` (every kind) last. */
  readonly levels: readonly (readonly string[])[];
}

/**
 * The merged S6's B2 (the reviewer's unrestricted-collection matrix, rebuilt by axes): `list`, `set` and `dict`, plain,
 * optional or as a list's element (`list[]`) × known contents (an integer, text, a boolean, `null`, a nested list) ×
 * how they arrive: the initial value, a named value, a later store into an initially empty one, or a copy of the written
 * collection, at the end of a chain of one to three copies, that then takes them. Nothing is owed: no diagnostic, no check, the run says DONE. The host-fed controls
 * are `writtenCase`s of the unrestricted names.
 */
export const UNRESTRICTED_COLLECTION_MATRIX: readonly UnrestrictedCase[] = (() => {
  const out: UnrestrictedCase[] = [];
  const shell = (kind: Collection, inner: string): string =>
    kind === "list" ? `[${inner}]` : kind === "set" ? `set[${inner}]` : `dict{a: ${inner}}`;
  const empty = (kind: Collection): string =>
    kind === "list" ? "[]" : kind === "set" ? "set[]" : "dict{}";
  for (const kind of ["list", "set", "dict"] as const)
    for (const shape of ["plain", "optional", "nested"] as const)
      for (const [content, contentName] of [
        ["1", "an integer"],
        ['"text"', "text"],
        ["true", "a boolean"],
        ["null", "null"],
        ["[1]", "a nested list"],
      ] as const)
        for (const arrival of [
          "initial",
          "named",
          "later",
          "copy",
          "copy of a copy",
          "copy of a copy of a copy",
        ] as const) {
          const type = shape === "plain" ? kind : shape === "optional" ? `${kind}?` : `${kind}[]`;
          const known = (inner: string): string =>
            shape === "nested" ? `[${shell(kind, inner)}]` : shell(kind, inner);
          const blank = shape === "nested" ? "[]" : empty(kind);
          const place = arrival.startsWith("copy") ? "copy" : "out";
          const chain =
            arrival === "copy"
              ? ["let copy = out"]
              : arrival === "copy of a copy"
                ? ["let middle = out", "let copy = middle"]
                : ["let first = out", "let second = first", "let copy = second"];
          const lines =
            arrival === "initial"
              ? [`let out: ${type} = ${known(content)}`]
              : arrival === "named"
                ? [`let v = ${content}`, `let out: ${type} = ${known("v")}`]
                : arrival === "later"
                  ? [`let out: ${type} = ${blank}`, `out = ${known(content)}`]
                  : [`let out: ${type} = ${blank}`, ...chain, `copy = ${known(content)}`];
          const levels: string[][] =
            shape === "nested"
              ? [["list"], [kind], ["unknown"]]
              : [shape === "optional" ? [kind, "null"].sort() : [kind], ["unknown"]];
          out.push({
            name: `${type} holding ${contentName}, ${arrival}`,
            source: `${[...lines, 'say "DONE"', "exit"].join("\n")}\n`,
            place,
            path: Array<string>(levels.length - 1).fill("element"),
            levels,
          });
        }
  return out;
})();

/**
 * Sol's round 1 on #1049 (B2's invariant through optionals, unions and projections): an `object`'s properties admit
 * every kind (V30 §13; r4.74 (2)) in each form that holds one, `object`, `object?`, `object | string`, and as a list's
 * element at depths 1 and 2, optional or in a union too × the property's contents (an integer, text, a boolean, `null`,
 * a list, the host value) × the place written, a copy of it at the end of a chain of one to three copies, a copy of the
 * property (a projection) or a copy of that copy, a copy of a place typed after a `null` start, each then taking them. Nothing is owed: no diagnostic, no check, no
 * boundary. The candidate route does not take object literals: the decision layer only.
 */
export const OBJECT_PROPERTY_MATRIX: readonly UnrestrictedCase[] = (() => {
  const out: UnrestrictedCase[] = [];
  const object = name("object");
  const forms = [
    object,
    optional(object),
    union(object, name("string")),
    collection("list", object),
    collection("list", optional(object)),
    collection("list", union(object, name("string"))),
    optional(collection("list", object)),
    collection("list", collection("list", object)),
    collection("list", collection("list", optional(object))),
  ];
  for (const form of forms) {
    const type = formText(form);
    const index = "[0]".repeat(depthOf(form));
    const property = [...Array<string>(depthOf(form)).fill("element"), "p"];
    for (const [content, contentName] of [
      ["1", "an integer"],
      ['"text"', "text"],
      ["true", "a boolean"],
      ["null", "null"],
      ["[1]", "a list"],
      ["hostValue", "the host value"],
    ] as const)
      for (const arrival of [
        "written",
        "copy",
        "copy of a copy",
        "copy of a copy of a copy",
        "projection",
        "copy of a projection",
        "copy of a later-typed copy",
      ] as const) {
        const projected = arrival === "projection" || arrival === "copy of a projection";
        const place = arrival === "written" ? "typed" : "copy";
        const chain: Record<typeof arrival, readonly string[]> = {
          written: [],
          copy: ["let copy = typed"],
          "copy of a copy": ["let middle = typed", "let copy = middle"],
          "copy of a copy of a copy": [
            "let first = typed",
            "let second = first",
            "let copy = second",
          ],
          projection: [`let copy = typed${index}.p`],
          "copy of a projection": [`let middle = typed${index}.p`, "let copy = middle"],
          "copy of a later-typed copy": [
            "let middle = null",
            "middle = typed",
            "let copy = middle",
          ],
        };
        const lines = [
          `let typed: ${type} = ${valueOf(form, "{p: 1}")}`,
          ...chain[arrival],
          projected ? `copy = ${content}` : `${place}${index}.p = ${content}`,
        ];
        out.push({
          name: `${type} holding ${contentName}, ${arrival}`,
          source: `${[...lines, 'say "DONE"', "exit"].join("\n")}\n`,
          place,
          path: projected ? [] : property,
          levels: projected ? [["unknown"]] : [...levelsOf(form), ["unknown"]],
        });
      }
  }
  return out;
})();

/**
 * V30 §13's written-type matrix (the orchestrator's instruction): every type name (the scalars, `null`, the
 * unrestricted `list`, `set`, `dict`, `object`, the program-control names) in each form §13 lists, `T`, `T?`, `T[]`,
 * `T set`, `T dict`, `T?[]`, `T[]?`, `T | U` and `(T | U)[]` (beside `string`, `integer` for a `string`), nested to depth
 * three (`T[][]`, `T?[][]`, `T[]?[]`, `T[] set`, `T[] dict`, `T[][][]`; `null?` is `null`), × the place written, an early
 * or a later copy, a copy at the end of a chain of two or three copies, for a list form a copy of its element (a typed
 * index projection) or a copy of that copy × the host value direct, named or held at an index; and for a form of depth
 * one at most a copy of a place typed by each seed (`SEEDS`), the host value direct. A union holding a whole collection
 * beside another type
 * is §13's compile error and has no form here: the compiler does not report it yet, pre-existing (r4.75 (3)).
 */
export const V30_TYPE_MATRIX: readonly WrittenCase[] = (() => {
  const out: WrittenCase[] = [];
  for (const base of [...SCALAR_NAMES, "null", ...UNRESTRICTED_NAMES, ...CONTROL_NAMES]) {
    const t = name(base);
    const other = name(base === "string" ? "integer" : "string");
    const collected = base !== "object" && UNRESTRICTED.has(base);
    // (`null?` is `null`: the optional forms of `null` are its plain ones)
    const opt = (of: Form): Form => (base === "null" ? of : optional(of));
    const forms: Form[] = [
      t,
      ...(base === "null" ? [] : [optional(t)]),
      collection("list", t),
      collection("set", t),
      collection("dict", t),
      ...(base === "null" ? [] : [collection("list", opt(t))]),
      optional(collection("list", t)),
      collection("list", collection("list", t)),
      ...(base === "null" ? [] : [collection("list", collection("list", opt(t)))]),
      collection("list", optional(collection("list", t))),
      collection("set", collection("list", t)),
      collection("dict", collection("list", t)),
      collection("list", collection("list", collection("list", t))),
      // a union never holds a whole collection beside another type (§13): unions of the others only
      ...(collected ? [] : [union(t, other), collection("list", union(t, other))]),
    ];
    for (const form of forms) {
      if (depthOf(form) > 3) continue;
      const list = form.kind === "collection" && form.collection === "list";
      for (const decision of [...DECISIONS, ...(list ? PROJECTIONS : [])])
        for (const host of HOSTS) out.push(writtenCase(form, decision, host));
      // (the seeds with the host value direct: every placement of it is the written-domain matrix's)
      if (depthOf(form) <= 1)
        for (const decision of SEEDS) out.push(writtenCase(form, decision, "direct"));
    }
  }
  return out;
})();

/**
 * The reviewer's Q1, ruled (ADR 0021 §1.2: an unannotated `integer` "is a `number` when any of them can store a non-whole
 * number, wherever that assignment is"; §1.1: "the decided type holds wherever the place is used, also before the value
 * that decided it"; TABLE r4.28): a copy of an unannotated source has the source's whole-source type, so a fraction or a
 * `null` stored into the source after the copy was taken widens the copy too, as it would before it. A2's value at the
 * store's node only selects the decider. Axes: a fraction or a `null` × list depths 0–2 × the copy taken before or after
 * that store × the host value direct, named or held at an index; the host value then stored into the copy.
 */
export const INFERRED_COPY_MATRIX: readonly WrittenCase[] = (() => {
  const out: WrittenCase[] = [];
  const wrap = (inner: string, depth: number): string =>
    "[".repeat(depth) + inner + "]".repeat(depth);
  for (const [widening, leafKinds] of [
    ["2.5", ["number"]],
    ["null", ["integer", "null"]],
  ] as const)
    for (const depth of [0, 1, 2])
      for (const copied of ["before", "after"] as const)
        for (const host of HOSTS) {
          const leaf = host === "direct" ? "hostValue" : host === "named" ? "h" : "[hostValue][0]";
          const value = wrap(leaf, depth);
          const hostLine = `copy = ${value}`;
          const lines = [
            ...(host === "named" ? ["let h = hostValue"] : []),
            `let original = ${wrap("1", depth)}`,
            ...(copied === "before" ? ["let copy = original"] : []),
            `original = ${wrap(widening, depth)}`,
            ...(copied === "after" ? ["let copy = original"] : []),
            hostLine,
          ];
          const source = `${[...lines, 'say "DONE"', "exit"].join("\n")}\n`;
          const start = source.indexOf(`${hostLine}\n`);
          const end = start + hostLine.length;
          const kinds: string[] = [...leafKinds].sort();
          const levels = [...Array.from({ length: depth }, () => ["list"]), kinds];
          out.push({
            name: `${widening} into the source ${copied} the copy, depth ${depth}, ${host}`,
            source,
            place: "copy",
            form: wrap(kinds.join("|"), 0),
            decision: `copy ${copied} the store`,
            levels,
            checks: [
              `${start}:${end} ${"list<".repeat(depth)}${kinds.join("|")}${">".repeat(depth)}`,
            ],
            exact: true,
            runs: HOST_VALUES.map(([given, is]) => [
              given,
              is.some((kind) => kinds.includes(kind))
                ? null
                : `TSR058@${end - value.length}:${end}`,
            ]),
            boundaries:
              host === "named"
                ? [`h 0 [unknown] ${siteIn(source, "let h = hostValue", "hostValue")}`]
                : boundaryAt("copy", levels, depth, siteIn(source, hostLine, "hostValue")),
          });
        }
  return out;
})();

/**
 * A chain through an unannotated parameter's default (F21, ADR 0021 1.5: the default is the parameter's start value,
 * checked once at the function against the body, and an argument beside it decides nothing; r4.75 (1)): `p = typed`
 * makes `p` a copy of the written binding, so `let out = p` in the body has its type, with a call before or after the
 * function, or two calls, each passing another kind. A function is outside the candidate slice: the decision layer only.
 */
export const DEFAULT_CHAIN_MATRIX: readonly WrittenCase[] = (() => {
  const out: WrittenCase[] = [];
  for (const form of [name("null"), optional(name("integer")), collection("list", name("string"))])
    for (const calls of ["a call before", "a call after", "two calls"] as const) {
      const type = formText(form);
      const call = `use(${leafKinds(form).includes("string") ? "true" : '"other"'})`;
      const lines = [
        `let typed: ${type} = ${valueOf(form, leafLiteral(form)!)}`,
        ...(calls === "a call before" ? [call] : []),
        "function use(p = typed) {",
        " let out = p",
        " out = hostValue",
        "}",
        ...(calls === "a call after" ? [call] : calls === "two calls" ? [call, call] : []),
      ];
      const source = `${[...lines, "exit"].join("\n")}\n`;
      const levels = levelsOf(form);
      out.push({
        name: `${type}, a copy of the default, ${calls}`,
        source,
        place: "out",
        form: type,
        decision: "a copy of the default",
        levels,
        checks: [],
        exact: true,
        runs: [],
        boundaries: boundaryAt("out", levels, 0, siteIn(source, " out = hostValue", "hostValue")),
      });
    }
  return out;
})();
